java
public void startPlaytimeTracking(Player player) {
    if (player == null || !player.isOnline()) {
        return;
    }

    UUID playerId = player.getUniqueId();
    long startTime = System.currentTimeMillis();

    playtimeMap.put(playerId, startTime);

    player.sendMessage("Playtime tracking started!");

    Bukkit.getScheduler().runTaskLater(this, () -> {
        long totalTime = System.currentTimeMillis() - playtimeMap.get(playerId);
        player.sendMessage("Your total playtime is: " + formatTime(totalTime));
    }, 72000L); // Schedule for 2 hours later, adjust as needed
}

private String formatTime(long millis) {
    long seconds = millis / 1000;
    long minutes = seconds / 60;
    long hours = minutes / 60;
    seconds %= 60;
    minutes %= 60;

    return String.format("%02d:%02d:%02d", hours, minutes, seconds);
}

