public class ClassificationRuleFunction extends RuleFunction {

    @Override
    public double evaluate(Rule rule, Dataset dataset) {
        double score = 0.0;
        int totalInstances = dataset.size();
        int correctInstances = 0;

        for (Instance instance : dataset) {
            if (rule.applies(instance)) {
                correctInstances += (instance.getLabel() == rule.getLabel()) ? 1 : 0;
            }
        }

        if (totalInstances > 0) {
            score = (double) correctInstances / totalInstances;
        }

        return score;
    }
}

