public abstract class ClassificationRuleFunction extends RuleFunction {

    public abstract double evaluate(ClassificationRule rule, Dataset dataset);

    public double evaluate(Rule rule, Dataset dataset) {
        if (!(rule instanceof ClassificationRule)) {
            throw new IllegalArgumentException("Rule must be an instance of ClassificationRule");
        }
        return evaluate((ClassificationRule) rule, dataset);
    }

    protected double calculateCost(ClassificationRule rule, Dataset dataset) {
        double totalCost = 0.0;
        for (Instance instance : dataset) {
            if (rule.applies(instance)) {
                totalCost += Cost.getCost(instance);
            }
        }
        return totalCost;
    }
}

