public double evaluate(Rule rule, Dataset dataset) {
    double score = 0.0;
    int correct = 0;
    int total = 0;

    for (Instance instance : dataset) {
        if (rule.appliesTo(instance)) {
            total++;
            if (rule.classify(instance) == instance.getLabel()) {
                correct++;
            }
        }
    }

    if (total > 0) {
        score = (double) correct / total;
    }

    return score;
}

