        Level level = record.getLevel();

        // Log using Log4j
        switch (level.getName()) {
            case "SEVERE":
                logger.error(message);
                break;
            case "WARNING":
                logger.warn(message);
                break;
            case "INFO":
                logger.info(message);
                break;
            case "CONFIG":
                logger.debug(message);
                break;
            case "FINE":
            case "FINER":
            case "FINEST":
                logger.trace(message);
                break;
            default:
                logger.info(message);
                break;
        }
    }

