  protected void updateClusterStatus(ClusterMetrics metrics) {
    if (metrics == null) {
      LOG.warn("Received null cluster metrics update.");
      return;
    }

    List<ServerName> currentDeadServers = metrics.getDeadServers();
    for (ServerName server : currentDeadServers) {
      if (!deadServers.contains(server)) {
        deadServers.add(server);
        deadServerHandler.handleDeadServer(server);
        LOG.info("Handled dead server: {}", server);
      }
    }

    if (listener != null) {
      listener.onClusterStatusUpdate(metrics);
    }
  }
