public void editFile(WikiRequest request) throws WikiException {
    String fileName = request.getParameter(RequestParameter.FILE_NAME);
    String fileContent = request.getParameter(RequestParameter.FILE_CONTENT);

    if (fileName == null || fileName.isEmpty()) {
        throw new WikiException("File name cannot be null or empty.");
    }

    if (fileContent == null) {
        throw new WikiException("File content cannot be null.");
    }

    // Assuming a method saveFile exists to handle the file saving logic
    boolean isSaved = saveFile(fileName, fileContent);

    if (!isSaved) {
        throw new WikiException("Failed to save the file: " + fileName);
    }

    // Print success message
    HtmlLinePrinter printer = new HtmlLinePrinter();
    printer.println("File " + fileName + " has been successfully edited.");
}

