java
public void editFile(WikiRequest request) throws WikiException {
    String fileName = request.getParameter(RequestParameter.FILE_NAME);
    String fileContent = request.getParameter(RequestParameter.FILE_CONTENT);

    if (fileName == null || fileContent == null) {
        throw new WikiException("File name or content cannot be null.");
    }

    // Logic to edit the file
    File file = new File(fileName);
    if (!file.exists()) {
        throw new WikiException("File does not exist.");
    }

    try (FileWriter fileWriter = new FileWriter(file)) {
        fileWriter.write(fileContent);
    } catch (IOException e) {
        throw new WikiException("Error writing to file: " + e.getMessage(), e);
    }

    // Print success message
    HtmlLinePrinter printer = new HtmlLinePrinter(request);
    printer.print("File edited successfully: " + fileName);
}

