    private void configureProperties(ModelNode model) {
        Map<String, String> properties = new HashMap<>();
        for (String attribute : model.keys()) {
            if (!attribute.equals(NAME.getName())) {
                properties.put(attribute, model.get(attribute).asString());
            }
        }
        // Logic to apply properties to the protocol
        JGroupsLogger.LOGGER.configuringProperties(properties);
    }

