java
    // Implementation for the method body
    public void configureProtocol(OperationContext context, ResourceServiceBuilder<?> builder, List<ProtocolFactory> protocolFactories) throws OperationFailedException {
        Map<String, Object> attributes = new HashMap<>();

        for (ProtocolFactory factory : protocolFactories) {
            try {
                Optional<Method> configureMethod = findConfigureMethod(factory);
                if (configureMethod.isPresent()) {
                    configureMethod.get().invoke(factory, context, attributes);
                }
            } catch (ReflectiveOperationException e) {
                throw new OperationFailedException(Errors.failedToInvokeMethod(e.getMessage()), e);
            }
        }

        // Apply the attributes to the builder
        attributes.forEach(builder::setAttribute);
    }

    private Optional<Method> findConfigureMethod(ProtocolFactory factory) {
        return Arrays.stream(factory.getClass().getMethods())
            .filter(method -> method.getName().equals("configure") && method.getParameterCount() == 2)
            .findFirst();
    }

